import{_ as r,a as n,b as c,c as h}from"./chunks/cYcYfM9Mvwo-1280.ga3xMC1O.js";import{_ as w,C as o,o as d,c as u,j as t,a,E as s,a8 as p}from"./chunks/framework.27XeWUA0.js";const T=JSON.parse('{"title":"AI Digest · Sat 28 Nov 2026","description":"","frontmatter":{"aside":false,"outline":false},"headers":[],"params":{"date":"2026-11-28","routine":"digest"},"relativePath":"digest/2026-11-28.md","filePath":"digest/[date].md"}'),m={name:"digest/2026-11-28.md"},g=r+" 640w, "+c+" 1280w",v=n+" 640w, "+h+" 1280w",f={id:"ai-digest-·-sat-28-nov-2026",tabindex:"-1"};function b(y,e,k,M,_,Y){const i=o("Badge"),l=o("DayFilter");return d(),u("div",null,[t("h1",f,[e[0]||(e[0]=a("AI Digest · Sat 28 Nov 2026 ",-1)),s(i,{type:"tip",text:"2"}),e[1]||(e[1]=a()),e[2]||(e[2]=t("a",{class:"header-anchor",href:"#ai-digest-·-sat-28-nov-2026","aria-label":'Permalink to "AI Digest · Sat 28 Nov 2026 <Badge type="tip" text="2" />"'},"​",-1))]),e[3]||(e[3]=t("p",{class:"sub"},"AI Engineer + Better Stack daily digest — 28 Nov 2026 · run date Sat 28 Nov 2026 · 2 videos",-1)),e[4]||(e[4]=t("div",{class:"overview"},[t("p",null,[t("strong",null,"AI Engineer:"),a(' There are 2 new talks, and both are about decision models (the "Jev" System 1 idea, seen 12 times before). The freshest is Chinmay Goyal (Glean) with hard production numbers from swapping LLM calls for Jev (28 Nov, 1:30 AM IST): worth watching. Before that, Michelle Chen tells why Cloudflare trained its own decision models, Clef and Cleric, and demos them on CI triage (27 Nov, 7:30 PM IST): skim from 8:03.')]),t("p",null,[t("strong",null,"Better Stack:"),a(" No new main-channel video in the last 24 hours. Only Shorts were posted (a Rust Prettier clip, NVIDIA long context, cheap AI API risks, a Microsoft email outage, Claude cheating), so there's no Better Stack section today.")])],-1)),s(l),e[5]||(e[5]=p('<div class="grid cards2"><article class="it full" id="v-K5_ST-kMrvY" data-title="Stop Paying LLM Prices for Yes-or-No Answers — Chinmay Goyal, Glean" data-channel="AI Engineer" data-verdict="worth"><a class="th" href="https://www.youtube.com/watch?v=K5_ST-kMrvY" target="_blank" rel="noopener"><img src="'+r+'" srcset="'+g+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-worth">worth</span><h3><a href="https://www.youtube.com/watch?v=K5_ST-kMrvY" target="_blank" rel="noopener">Stop Paying LLM Prices for Yes-or-No Answers — Chinmay Goyal, Glean</a></h3><div class="meta">AI Engineer · Chinmay Goyal, software engineer on Glean Assistant · uploaded 28 Nov, 1:30 AM IST · 16:05</div><div class="verdict v-worth"><b>Verdict:</b> worth watching — short (16 min) and full of real production numbers (8× latency, 99.2% on time, recall from 31.5% to 90.2%). This is the clearest case so far for decision models, even though the topic itself is well covered.</div><div class="repeat">🔁 Repeat: &#39;decision models&#39; — seen 12 times before. New here: a production report from a big customer: measured results from swapping general LLM calls for Jev (TypeSafe&#39;s decision model) at five separate steps inside Glean, not a demo or a launch.</div><div class="repeat">🔁 Repeat: &#39;LLM-as-a-judge&#39; — seen 22 times before. New here: a decision model used as the judge for citation checks gave the same answer on nearly every repeat run, so they no longer re-run each check several times.</div><div class="sh">Why a decision model</div><ul><li><strong>Most steps are decisions, not generation:</strong> Classifying a query&#39;s intent, picking one of N suggestions, checking a citation and routing to the right expert are bounded choices, yet Glean paid full LLM cost and latency for each (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=36s" target="_blank" rel="noopener">0:36</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=90s" target="_blank" rel="noopener">1:30</a>)</li><li><strong>Options compared:</strong> A general LLM is slow and costly. A fine-tuned open model has to be retrained whenever the label set changes. With Jev they just edit the prompt, but it can&#39;t write free text (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=88s" target="_blank" rel="noopener">1:28</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=135s" target="_blank" rel="noopener">2:15</a>)</li><li><strong>How changes ship:</strong> Every change runs against a golden eval set, then a couple of weeks of internal use by about 1,500 Glean employees, then A/B tests with customers (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=135s" target="_blank" rel="noopener">2:15</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=195s" target="_blank" rel="noopener">3:15</a>)</li></ul><div class="sh">Results in the product</div><ul><li><strong>Query classification:</strong> On Glean&#39;s test set, Jev nearly doubled the quality of a base Llama model and reached about 90% of a fine-tuned Llama, without collecting data, training or hosting anything (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=195s" target="_blank" rel="noopener">3:15</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=275s" target="_blank" rel="noopener">4:35</a>)</li><li><strong>Expert routing:</strong> Compared with the general LLM router, Jev had noticeably higher precision at almost 8× lower latency. It needed real infrastructure changes, and he calls it one of the rare places where extra complexity was worth it (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=275s" target="_blank" rel="noopener">4:35</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=340s" target="_blank" rel="noopener">5:40</a>)</li><li><strong>Follow-up suggestion ranker (&quot;Q&quot;):</strong> Picking the best of 10–15 generated suggestions has a 1.5–2 s budget. Jev met it 99.2% of the time versus about 90% for the LLM, and gave zero invalid outputs (the LLM sometimes answered in the wrong language, for example). Because Jev returns a probability for each option, per-customer thresholds now tune themselves (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=340s" target="_blank" rel="noopener">5:40</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=585s" target="_blank" rel="noopener">9:45</a>)</li></ul><div class="sh">Dev pipeline and security</div><ul><li><strong>Citation checks:</strong> Asking whether a cited document really supports a claim was faster and cheaper with Jev. Only one of the 28–30 test cases changed across runs, which he says lets each engineer ship about 5–6× faster (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=595s" target="_blank" rel="noopener">9:55</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=750s" target="_blank" rel="noopener">12:30</a>)</li><li><strong>Security classifier:</strong> In the recall-heavy first stage that screens tool and LLM inputs and outputs, Jev replaced a classifier Glean hosted on T4 GPUs in every single-tenant customer deployment. Recall went from 31.5% to 90.2%, savings were &quot;far more than 50%&quot;, and 2–3 engineers no longer have to maintain those classifiers (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=750s" target="_blank" rel="noopener">12:30</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=865s" target="_blank" rel="noopener">14:25</a>)</li><li><strong>Rule of thumb:</strong> Can the possible outputs be listed in advance? If not, use a text LLM. If yes, use Jev. Fine-tune only when labels are stable and volume is high, which he says is rare now (<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=883s" target="_blank" rel="noopener">14:43</a>–<a href="https://www.youtube.com/watch?v=K5_ST-kMrvY&amp;t=930s" target="_blank" rel="noopener">15:30</a>)</li></ul></div></article><article class="it full" id="v-cYcYfM9Mvwo" data-title="Why Cloudflare Became a Neolab — Michelle Chen, Cloudflare" data-channel="AI Engineer" data-verdict="skim"><a class="th" href="https://www.youtube.com/watch?v=cYcYfM9Mvwo" target="_blank" rel="noopener"><img src="'+n+'" srcset="'+v+'" sizes="(max-width: 640px) 100vw, 240px" alt="" loading="lazy" decoding="async" width="640" height="360"></a><div class="bd"><span class="chip">AI Engineer</span><span class="chip warn">repeat</span><span class="chip v-skim">skim</span><h3><a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo" target="_blank" rel="noopener">Why Cloudflare Became a Neolab — Michelle Chen, Cloudflare</a></h3><div class="meta">AI Engineer · Michelle Chen, group PM for Workers AI, AI Search and AI Gateway at Cloudflare · uploaded 27 Nov, 7:30 PM IST · 20:06</div><div class="verdict v-skim"><b>Verdict:</b> skim from 8:03 — the first 8 minutes are Cloudflare company history. The Clef/Cleric story and the CI-triage numbers are concrete, but they overlap heavily with this morning&#39;s Glean talk and earlier Jev coverage.</div><div class="repeat">🔁 Repeat: &#39;decision models&#39; — seen 12 times before. New here: the inside story of why Cloudflare built its own Jev-style models (Jev was closed, so Cloudflare couldn&#39;t host it), and a CI-triage demo pairing them with an LLM. Clef itself was already covered by a Better Stack test on 5 Oct.</div><div class="repeat">🔁 Repeat: &#39;structured extraction&#39; — seen 8 times before. New here: Cleric, a one-forward-pass &quot;extraction model&quot; that turns emails, tickets, logs or images into typed JSON.</div><div class="sh">How Cloudflare got here</div><ul><li><strong>From CDN to developer platform:</strong> Cloudflare launched its own global network in 2010, added Workers (serverless functions that start in milliseconds) in 2017, then Durable Objects and, in 2025, containers, plus storage (KV, R2, D1) so whole apps can run on it (repeat) (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=120s" target="_blank" rel="noopener">2:00</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=245s" target="_blank" rel="noopener">4:05</a>)</li><li><strong>A wrong bet on small models:</strong> Workers AI launched in 2023 with GPUs near users, betting that models would shrink and network latency would matter more. Instead models went from 7B to about 3T parameters (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=248s" target="_blank" rel="noopener">4:08</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=365s" target="_blank" rel="noopener">6:05</a>)</li><li><strong>The pivot to big models:</strong> From March 2026 Cloudflare started serving Kimi, then GLM and DeepSeek, as part of its &quot;agent cloud&quot; pitch. She admits it never fit their infrastructure (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=365s" target="_blank" rel="noopener">6:05</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=470s" target="_blank" rel="noopener">7:50</a>)</li></ul><div class="sh">Becoming a &quot;neolab&quot;</div><ul><li><strong>Jev as the &quot;east wind&quot;:</strong> TypeSafe&#39;s Jev (Sept 2026) brought System 1 models: one forward pass instead of slow autoregressive generation. This proved the original small-and-fast bet &quot;wasn&#39;t wrong, just early&quot; (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=483s" target="_blank" rel="noopener">8:03</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=580s" target="_blank" rel="noopener">9:40</a>)</li><li><strong>Clef in a weekend:</strong> Jev was closed source, so Cloudflare began experimenting three days after its 15 Sept launch, trained Clef over 48 hours one weekend and launched it the next week. They shipped four models in three weeks, so agents can make decisions without minutes of LLM reasoning or waiting on a human (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=580s" target="_blank" rel="noopener">9:40</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=700s" target="_blank" rel="noopener">11:40</a>)</li><li><strong>Cleric for extraction:</strong> Cleric takes unstructured input (email, tweets, Slack, images) and extracts, computes, estimates or forecasts values into typed JSON, which agents can then pass to Clef and finally an LLM (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=700s" target="_blank" rel="noopener">11:40</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=785s" target="_blank" rel="noopener">13:05</a>)</li></ul><div class="sh">Demo and results</div><ul><li><strong>CI triage:</strong> The usual way is five round trips with GLM 5.3, sending all 40 tools each time. The System 1 version uses Clef Flash to cut the list to about 10 tools, Cleric to pull the PR number and the exact error from 300–600 lines of logs, and one final LLM call (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=850s" target="_blank" rel="noopener">14:10</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=960s" target="_blank" rel="noopener">16:00</a>)</li><li><strong>Numbers:</strong> Same answer in 9.2 s instead of 17.2 s (about 2× faster), 72% cheaper, LLM calls down from five to one, about 94% fewer tokens. The live run showed 40,000 LLM tokens versus 1,800. Suggested uses: routers, spam/phishing/fraud decisions, extraction from web pages and support tickets (<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=960s" target="_blank" rel="noopener">16:00</a>–<a href="https://www.youtube.com/watch?v=cYcYfM9Mvwo&amp;t=1110s" target="_blank" rel="noopener">18:30</a>)</li></ul></div></article></div>',1))])}const L=w(m,[["render",b]]);export{T as __pageData,L as default};
